/**
 * One minimal, successful invocation per LIGHT_SHELL_COMMANDS entry. The
 * isolated integration suite runs each in the Dynamic Worker shell after
 * LIGHT_SHELL_SETUP, so an entry that stops working after a just-bash or
 * Cloudflare Computer upgrade fails the build instead of silently routing a
 * command to a shell that cannot run it.
 */

/** Run once in the sample directory before the samples. */
export const LIGHT_SHELL_SETUP = 'mkdir -p d && printf "b\\na\\na\\n" > a.txt && printf "x,1\\ny,2\\n" > c.csv'
  + ' && cp a.txt b.txt && gzip -k a.txt && tar -cf t.tar a.txt'

export const LIGHT_SHELL_SAMPLES = Object.freeze({
  ':': ':',
  '[': '[ -f a.txt ]',
  '[[': '[[ -f a.txt ]]',
  alias: 'alias ll="ls -l"',
  break: 'for i in 1 2; do break; done',
  cd: 'cd d',
  continue: 'for i in 1 2; do continue; done',
  declare: 'declare -a list=(1 2)',
  echo: 'echo ok',
  exit: 'exit 0',
  export: 'export FOO=1',
  false: '! false',
  local: 'f_local() { local x=1; }; true',
  printf: 'printf "%s\\n" ok',
  pwd: 'pwd',
  read: 'echo line | read value',
  readonly: 'readonly LOCKED=1',
  return: 'f_return() { return 0; }; true',
  set: 'set -e',
  shift: 'set -- a b; shift',
  test: 'test -f a.txt',
  true: 'true',
  type: 'type ls',
  unalias: 'alias ll=ls; unalias ll',
  unset: 'FOO=1; unset FOO',
  awk: "awk -F, '{ s += $2 } END { print s }' c.csv",
  base64: 'echo ok | base64',
  basename: 'basename /workspace/a.txt',
  cat: 'cat a.txt',
  chmod: 'chmod 644 a.txt',
  clear: 'clear',
  column: 'column -t -s, c.csv',
  comm: 'sort a.txt > s1 && sort b.txt > s2 && comm s1 s2',
  cp: 'cp a.txt copy.txt',
  cut: 'cut -d, -f1 c.csv',
  date: 'date +%Y',
  diff: 'diff a.txt b.txt',
  dirname: 'dirname /workspace/a.txt',
  du: 'du -s d',
  egrep: 'egrep "a|b" a.txt',
  expand: 'printf "\\tx\\n" | expand',
  expr: 'expr 1 + 1',
  fgrep: 'fgrep a a.txt',
  find: 'find . -name "*.txt"',
  fold: 'echo abcdef | fold -w 2',
  grep: 'grep a a.txt',
  gunzip: 'gunzip -c a.txt.gz',
  gzip: 'gzip -c a.txt > z.gz',
  head: 'head -1 a.txt',
  help: 'help',
  history: 'history',
  hostname: 'hostname',
  join: 'join s1 s2 || true',
  ln: 'ln -sf a.txt link.txt',
  ls: 'ls',
  md5sum: 'md5sum a.txt',
  mkdir: 'mkdir -p e/f',
  mv: 'cp a.txt m.txt && mv m.txt n.txt',
  nl: 'nl a.txt',
  od: 'echo ab | od -c',
  paste: 'paste a.txt b.txt',
  printenv: 'printenv HOME || true',
  readlink: 'readlink link.txt',
  rev: 'echo abc | rev',
  rg: 'rg a a.txt',
  rm: 'touch gone && rm gone',
  rmdir: 'mkdir -p gone.d && rmdir gone.d',
  sed: "sed -n '1p' a.txt",
  seq: 'seq 3',
  sha1sum: 'sha1sum a.txt',
  sha256sum: 'sha256sum a.txt',
  sleep: 'sleep 0',
  sort: 'sort a.txt',
  stat: 'stat a.txt',
  strings: 'strings a.txt',
  tac: 'tac a.txt',
  tail: 'tail -1 a.txt',
  tar: 'tar -tf t.tar',
  tee: 'echo ok | tee tee.txt',
  touch: 'touch new.txt',
  tr: 'echo abc | tr a-z A-Z',
  tree: 'tree d',
  uniq: 'sort a.txt | uniq',
  unexpand: 'echo "        x" | unexpand -a',
  wc: 'wc -l a.txt',
  whoami: 'whoami',
  zcat: 'zcat a.txt.gz',
  env: 'env FOO=1 printenv FOO',
  time: 'time true',
  timeout: 'timeout 5 true',
  xargs: 'echo a.txt | xargs cat',
})
